import AppKit

/// The two look-up sources' own marks beside their counts in a citation's preview (UX.md §39 "Looking the references
/// up"): their sites' icons, downloaded 2026-11-02 with the advisor's OK (Google Scholar's favicon.ico, 48 px; Semantic
/// Scholar's img/favicon.png, 32 px), kept here as PNG data so the app needs no resource bundle. They are the services'
/// trademarks: fine for the advisor's own use; check their terms before a public release.
enum SourceLogos {
    static let googleScholar = image("")
    static let semanticScholar = image("")

    private static func image(_ base64: String) -> NSImage? { Data(base64Encoded: base64).flatMap(NSImage.init(data:)) }
}
